select (e->>0)::uuid, e->>1, e->>2, e->>3, e->>4, e->>5, (e->>6)::uuid, (e->>7)::int, (e->>8)::int, 'active', (e->>9)::bool, (e->>10)::bool, (e->>11)::timestamptz from jsonb_array_elements('[["16ac4b91-5dc9-4bf0-ac00-04ab7c3d0f0b","raglan-kol-lacivert-tunik","Raglan Kol Lacivert Tunik","Raglan kol kesimi ve yaka detayındaki ince taş işlemesiyle günlük şıklığın en rahat hali. Diz altı boyu ve hafif A kesimiyle her bedene uyum sağlar.","%95 Viskon, %5 Elastan. Model 1,72 m ve 38 beden giyiyor. Boy: 105 cm.","30°C''de tersten yıkayın. Ağartıcı kullanmayın. Düşük ısıda ütüleyin.","82d0bebb-8ae7-4627-af2d-9ccb54e5ae40",109900,139900,false,true,"2026-10-01T00:00:00.000Z"],["a0a5a049-58bf-4690-a1f6-097f9856ee2e","pliseli-lacivert-uzun-etek","Pliseli Lacivert Uzun Etek","Önden fermuar detaylı, beli lastikli pliseli uzun etek. Tunik ve gömleklerle kolayca kombinlenir.","%100 Polyester. Boy: 95 cm.","30°C''de tersten yıkayın. Ağartıcı kullanmayın. Düşük ısıda ütüleyin.","89f2eb1b-41a0-4b50-ad7e-29e9210f549a",84900,null,true,false,"2026-10-26T01:00:00.000Z"],["5130ab1f-070b-4064-a867-0117101c8095","denim-gorunumlu-yelek-takim","Denim Görünümlü Yelek Takım","Nakış detaylı beyaz gömlek tunik ve denim görünümlü uzun yelekten oluşan iki parça takım. Etek ucundaki fırfır detayı ile farklı bir görünüm.","Yelek: %70 Pamuk, %30 Polyester. Tunik: %100 Pamuk.","30°C''de tersten yıkayın. Ağartıcı kullanmayın. Düşük ısıda ütüleyin.","de184309-82bc-4882-a064-0a803a72bd5b",169900,199900,true,true,"2026-10-26T02:00:00.000Z"],["a340cd8e-531f-4ee3-abec-23359d4bbad7","batik-desen-triko-tunik","Batik Desen Triko Tunik","Önünde batik etkili desen bulunan, yumuşak dokulu triko tunik. Serin havalarda tek başına ya da gömlek üzerine giyilebilir.","%50 Yün, %50 Akrilik.","30°C''de yün programında yıkayın. Asmadan, serili kurutun.","e200b50b-5a8e-45c8-a66f-ba2dde25f4f9",124900,null,true,false,"2026-10-26T03:00:00.000Z"],["05beff01-bb34-4a82-a44b-99e6f7edada6","vizon-uzun-tunik","Vizon Uzun Tunik","Balon kol ve yırtmaç detaylı, sade ve zarif uzun tunik. Ofis ve günlük kullanım için ideal.","%100 Polyester krep. Boy: 115 cm.","30°C''de tersten yıkayın. Ağartıcı kullanmayın. Düşük ısıda ütüleyin.","82d0bebb-8ae7-4627-af2d-9ccb54e5ae40",99900,null,false,true,"2026-10-05T04:00:00.000Z"],["8b60ddc6-457e-48a6-a675-05523d4507a2","murdum-dalga-desen-takim","Mürdüm Dalga Desen Takım","Ön kısmı dalga desenli tunik ve aynı renk düz etekten oluşan şık takım. Özel günler için zahmetsiz bir kombin.","%95 Polyester, %5 Elastan.","30°C''de tersten yıkayın. Ağartıcı kullanmayın. Düşük ısıda ütüleyin.","de184309-82bc-4882-a064-0a803a72bd5b",154900,null,true,false,"2026-10-26T05:00:00.000Z"],["d255b802-770a-4952-abcc-98077c40da93","krem-batik-uzun-elbise","Krem Batik Uzun Elbise","Kemerli, hafif batik desenli uzun elbise. Akışkan kumaşı sayesinde yaz aylarında da rahat.","%100 Viskon. Boy: 140 cm.","30°C''de tersten yıkayın. Ağartıcı kullanmayın. Düşük ısıda ütüleyin.","4ade0eb5-5ea9-4c83-a0a1-2a82391a8a5a",139900,null,false,false,"2026-10-07T06:00:00.000Z"],["3b1f5b41-0dfe-430a-a61b-d214b10ce4ea","siyah-volan-yelek","Siyah Volan Detaylı Yelek","Tunik ve elbiselerin üzerine şık bir katman. Etek ucunda volan detayı.","%100 Polyester.","30°C''de tersten yıkayın. Ağartıcı kullanmayın. Düşük ısıda ütüleyin.","5abd744a-72de-40c8-a50b-9018c4115ae8",89900,null,false,false,"2026-10-08T07:00:00.000Z"],["4626a837-8c0b-45e1-a3ba-2ab4f9288e88","kahve-sal-desen-ipek-esarp","Kahve Şal Desen İpek Eşarp","Klasik şal (kaşmir) motifli, kenarı ince bordürlü ipeksi eşarp. Yumuşak dökümlü, kaymaz.","%100 Polyester ipeksi twill. Ölçü: 90 x 90 cm.","Elde soğuk suda yıkayın veya kuru temizleme. Sıkmadan gölgede kurutun.","718f3fc0-5aa7-475c-a629-557d34ee8426",54900,69900,false,true,"2026-10-09T08:00:00.000Z"],["9c2d455a-b515-48b4-a520-273d34e1446e","zumrut-sal-desen-esarp","Zümrüt Şal Desen Eşarp","Zümrüt yeşili zemin üzerinde altın tonlu şal desenleri. Koyu renk kombinlerin yıldızı.","%100 Polyester ipeksi twill. Ölçü: 90 x 90 cm.","Elde soğuk suda yıkayın veya kuru temizleme. Sıkmadan gölgede kurutun.","718f3fc0-5aa7-475c-a629-557d34ee8426",49900,null,true,false,"2026-10-26T09:00:00.000Z"],["9b0d4faf-679b-4c9d-a053-24139adbe169","zebra-desen-twill-esarp","Zebra Desen Twill Eşarp","Zebra ve leopar desenlerinin bir araya geldiği modern twill eşarp.","%100 Polyester twill. Ölçü: 90 x 90 cm.","Elde soğuk suda yıkayın veya kuru temizleme. Sıkmadan gölgede kurutun.","718f3fc0-5aa7-475c-a629-557d34ee8426",52900,null,true,false,"2026-10-26T10:00:00.000Z"],["bb43bb08-7274-430f-a4e2-1e3b50623cca","haki-dalga-desen-esarp","Haki Dalga Desen Eşarp","Haki ve bej tonlarında dalga desenli, günlük kullanıma uygun eşarp.","%100 Polyester. Ölçü: 90 x 90 cm.","Elde soğuk suda yıkayın veya kuru temizleme. Sıkmadan gölgede kurutun.","718f3fc0-5aa7-475c-a629-557d34ee8426",45900,null,false,false,"2026-10-12T11:00:00.000Z"],["4cf9bacd-211c-449e-ae13-bc7a43ff3fee","pudra-cicek-desen-sal","Pudra Çiçek Desen Şal","Hafif ve nefes alan, pudra zeminde küçük çiçek desenli uzun şal.","%100 Viskon. Ölçü: 75 x 200 cm.","Elde soğuk suda yıkayın veya kuru temizleme. Sıkmadan gölgede kurutun.","718f3fc0-5aa7-475c-a629-557d34ee8426",38900,null,false,false,"2026-10-13T12:00:00.000Z"],["9d9f18e7-7918-4cf5-aba5-9278e9a8100a","mint-desenli-kadin-pijama-takimi","Mint Desenli Kadın Pijama Takımı","Düz mint üst ve yaprak desenli alt. Pamuklu dokusuyla tüm gün rahatlık.","%100 Pamuk penye.","30°C''de tersten yıkayın. Ağartıcı kullanmayın. Düşük ısıda ütüleyin.","cefe494a-55be-4d4c-a44c-b3649595dbf6",89900,109900,false,true,"2026-10-14T13:00:00.000Z"],["aaa65ac9-fd90-41da-a8aa-4d3202fdbe9a","tropikal-desen-kadin-pijama","Tropikal Desen Kadın Pijama Takımı","Gömlek yaka, düğmeli tropikal desenli üst ve düz mavi alt.","%100 Viskon.","30°C''de tersten yıkayın. Ağartıcı kullanmayın. Düşük ısıda ütüleyin.","cefe494a-55be-4d4c-a44c-b3649595dbf6",94900,null,true,false,"2026-10-26T14:00:00.000Z"],["9081955f-7cf6-4df5-a60e-81ebb1709ba4","bordo-erkek-pijama-takimi","Bordo Erkek Pijama Takımı","Patlı yaka bordo üst ve çizgili alt. Yumuşak pamuklu kumaş.","%100 Pamuk.","30°C''de tersten yıkayın. Ağartıcı kullanmayın. Düşük ısıda ütüleyin.","f2b63e57-d2b5-440a-af5d-504e99d12574",99900,null,false,true,"2026-10-16T15:00:00.000Z"],["5f512562-389e-4ef8-adfe-6bca4400306b","sari-desenli-erkek-tisort","Sarı Desenli Erkek Tişört","Kolları lacivert biyeli, minimal desenli yazlık tişört.","%100 Pamuk.","30°C''de tersten yıkayın. Ağartıcı kullanmayın. Düşük ısıda ütüleyin.","d7e79622-d8b0-41d2-a065-a8b3fd23c099",44900,null,false,false,"2026-10-17T16:00:00.000Z"],["2ef1b233-87d8-41f8-a826-2cd0b627e41c","lacivert-polo-yaka-tisort","Lacivert Polo Yaka Tişört","Pike kumaştan klasik polo yaka tişört.","%100 Pamuk pike.","30°C''de tersten yıkayın. Ağartıcı kullanmayın. Düşük ısıda ütüleyin.","d7e79622-d8b0-41d2-a065-a8b3fd23c099",52900,null,false,false,"2026-10-18T17:00:00.000Z"],["61a62614-73a5-4676-a2df-1f79bc6fe73d","gri-sardonyks-tunik","Gri Ribana Kol Tunik","Ribana kol ağzı ve sade kesimiyle her güne uyan tunik.","%95 Viskon, %5 Elastan.","30°C''de tersten yıkayın. Ağartıcı kullanmayın. Düşük ısıda ütüleyin.","82d0bebb-8ae7-4627-af2d-9ccb54e5ae40",94900,null,false,false,"2026-10-19T18:00:00.000Z"],["6c70055f-5db6-4f2b-a605-c70e48927556","vizon-triko-takim","Vizon Triko Takım","Uzun triko hırka ve aynı renk triko etekten oluşan sıcak takım.","%30 Yün, %70 Akrilik.","30°C''de yün programında yıkayın. Serili kurutun.","e200b50b-5a8e-45c8-a66f-ba2dde25f4f9",179900,209900,false,false,"2026-10-20T19:00:00.000Z"]]'::jsonb) e on conflict (id) do nothing;
